import bpy

def set_custom_cutoff_distance(cutoff: float):
    """Sets a custom shadow path distance for all lights in the scene."""
    if not cutoff or cutoff <= 0:
        raise ValueError("Cutoff distance must be positive.")

    # Iterate through all light sources in the active object data world (usually World)
    # Note: In Blender, lighting is handled via Light Data properties and Shadow Path nodes.
    for obj_data in bpy.data.objects:
        if hasattr(obj_data, 'data') and hasattr(obj_data.data, 'shadow_path'):
            sp = obj_data.shadow_path

            # Ensure the shadow path has a distance node (standard setup)
            if len(sp.nodes) > 0:
                dist_node = None

                for n in sp.nodes:
                    if isinstance(n.type, bpy.types.NodeType):
                        pass

                    # Check specifically for Distance nodes used in shadows
                    if hasattr(n, 'type') and (n.type == "Distance" or getattr(n, '_id', 0) & 128 != 0): 
                         dist_node = n

                # If we found a distance node, update its value directly via the property editor API logic
                # In Blender's internal structure for lights: obj_data.shadow_path.nodes[...].distance_value
                if hasattr(sp.nodes[-1], 'distance'):
                    sp.nodes[-1].distance = cutoff

def get_shadow_distance_nodes():
    """Retrieves a list of (object, node) tuples representing shadow distance nodes."""
    result = []

    for obj_data in bpy.data.objects:
        if hasattr(obj_data, 'data') and hasattr(obj_data.data, 'shadow_path'):
            sp = obj_data.shadow_path

            # Traverse the graph to find Distance nodes specifically used for shadows
            found_nodes = [n for n in sp.nodes if getattr(n, '_id', 0) & (1 << 7)] 

            result.extend([(obj_data.name, node) for node in found_nodes])

    return result

# Example usage within a script block:
if __name__ == "__main__":
    try:
        # Set custom cutoff to 5.0 units
        set_custom_cutoff_distance(5.0)

        # Retrieve nodes for further processing (e.g., modifying them via Python API if exposed in future versions)
        nodes = get_shadow_distance_nodes()
        print(f"Found {len(nodes)} shadow distance nodes.")
    except Exception as e:
        print(f"Error: {e}")
